<script setup lang="ts">
import { ref, watch } from 'vue'
import ModalShell from '@/components/global/ModalShell.vue'
import BranchHoursEditor from '@/components/admin/BranchHoursEditor.vue'
import type { BranchForm } from './types'
const props = defineProps<{ open: boolean; editing: boolean; saving: boolean; form: BranchForm }>()
const emit = defineEmits<{ close: []; submit: [] }>()
const step = ref(3)
watch(() => props.open, (open) => { if (open) step.value = 3 })
function imageChange(event: Event) { const file = (event.target as HTMLInputElement).files?.[0] || null; props.form.imageFile = file; if (file) props.form.imagePreview = URL.createObjectURL(file) }
</script>

<template>
  <ModalShell :open="open" :title="editing ? 'Editar sucursal' : 'Nueva sucursal'" subtitle="Configura información, ubicación, operación y horarios en pocos pasos." size="lg" @close="emit('close')"><form class="wizard" @submit.prevent="emit('submit')"><aside class="preview"><div class="image"><img v-if="form.imagePreview" :src="form.imagePreview" :alt="form.name || 'Sucursal'" /><i v-else class="fa-solid fa-store" /></div><strong>{{ form.name || 'Nueva sucursal' }}</strong><small>{{ form.city || 'Ciudad por definir' }}</small><label><input type="file" accept="image/*" @change="imageChange" /><i class="fa-solid fa-image" /> {{ form.imagePreview ? 'Cambiar imagen' : 'Subir imagen' }}</label></aside><section class="form"><nav><button v-for="(label, index) in ['Datos', 'Ubicación', 'Operación']" :key="label" type="button" :class="{ active: step === index + 1 }" @click="step = index + 1"><i :class="index === 0 ? 'fa-solid fa-store' : index === 1 ? 'fa-solid fa-location-dot' : 'fa-solid fa-clock'" />{{ label }}</button></nav><Transition name="wizard-step" mode="out-in"><div :key="step" class="fields"><template v-if="step === 1"><header><h2>Datos de la sucursal</h2><p>Estos datos identifican el local en el catálogo y operaciones.</p></header><label><span>Nombre</span><input v-model="form.name" required placeholder="Boloncity Garzota" /></label><label><span>Ciudad</span><input v-model="form.city" required placeholder="Guayaquil" /></label><label><span>Teléfono</span><input v-model="form.phone" required placeholder="+593 96 000 0000" /></label><label><span>Email</span><input v-model="form.email" required type="email" placeholder="local@boloncity.com" /></label></template><template v-else-if="step === 2"><header><h2>Ubicación</h2><p>Pega el enlace de Google Maps para extraer las coordenadas de atención y delivery.</p></header><label class="full"><span>Dirección</span><input v-model="form.address" required placeholder="Dirección completa del local" /></label><label class="full"><span>Google Maps <em>Recomendado</em></span><input v-model="form.googleMapsUrl" placeholder="https://maps.google.com/..." /><small>Se usa para encontrar la sucursal más cercana al cliente.</small></label></template><template v-else><header><h2>Operación</h2><p>Una sucursal inactiva no recibe pedidos. Los horarios bloquean pedidos fuera de atención.</p></header><label class="active-toggle"><input v-model="form.isActive" type="checkbox" /><span><strong>Sucursal activa</strong><small>Disponible para pedidos y asignación.</small></span></label><label class="full"><span>Store ID de PayPhone <em>Requerido para cobrar</em></span><input v-model.trim="form.payphoneStoreId" placeholder="00000000-0000-0000-0000-000000000000" /><small>Identifica la tienda de PayPhone de este local. Sin este dato el cobro cae en la tienda principal y no en la sucursal.</small></label><BranchHoursEditor v-model="form.openingHours" /></template></div></Transition><footer><button v-if="step > 1" type="button" class="secondary" @click="step--"><i class="fa-solid fa-arrow-left" /> Atrás</button><button v-if="step < 3" type="button" @click="step++">Siguiente <i class="fa-solid fa-arrow-right" /></button><button v-else type="submit" :disabled="saving"><i class="fa-solid fa-floppy-disk" /> {{ saving ? 'Guardando...' : editing ? 'Guardar cambios' : 'Crear sucursal' }}</button></footer></section></form></ModalShell>
</template>

